<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Document Layout</title>
<style>
  body {
    font-family: Arial, Helvetica, sans-serif;
    margin: 0;
    padding: 20px;
    background-color: #fff;
    color: #000;
  }
  .page-container {
    max-width: 1000px;
    margin: 0 auto;
  }
  .grid {
    display: grid;
    grid-template-columns: 300px 1fr 1fr;
    gap: 40px;
  }

  /* Placeholder Style */
  .placeholder {
    background-color: #f9f9f9;
    border: 1px dashed #999;
    color: #666;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    font-style: italic;
    font-size: 12px;
  }

  /* Left Column */
  .col-left {
    grid-column: 1;
    grid-row: 1 / span 2;
    display: flex;
    flex-direction: column;
    gap: 30px;
  }

  /* Weber Ad */
  .weber-ad {
    border: 2px solid #000;
    padding: 15px;
  }
  .weber-header {
    font-size: 11px;
    margin-bottom: 15px;
  }
  .weber-catalog {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 15px;
  }
  .weber-catalog-img {
    width: 120px;
    height: 80px;
  }
  .weber-catalog-text {
    font-weight: bold;
    font-size: 14px;
    line-height: 1.2;
  }
  .weber-text {
    font-size: 10px;
    text-align: justify;
    margin-bottom: 15px;
    line-height: 1.3;
  }
  .weber-mfg {
    font-size: 12px;
    font-style: italic;
    margin-bottom: 10px;
  }
  .weber-logo-container {
    margin-bottom: 10px;
  }
  .weber-logo-box {
    border: 2px solid #000;
    padding: 5px 20px;
    display: inline-block;
    font-weight: 900;
    font-size: 24px;
    letter-spacing: 3px;
  }
  .weber-company {
    font-size: 12px;
    margin-bottom: 15px;
    line-height: 1.3;
  }
  .weber-contact {
    font-size: 12px;
    margin-bottom: 15px;
    line-height: 1.4;
  }
  .weber-contact strong {
    font-size: 13px;
  }
  .weber-installations {
    font-size: 9px;
    line-height: 1.3;
  }

  /* Ben Meadows Ad */
  .ben-ad-container {
    display: flex;
    flex-direction: column;
  }
  .ben-bubble {
    border: 8px solid #000;
    padding: 20px;
    position: relative;
    margin-bottom: 40px;
  }
  .ben-pointer-solid {
    position: absolute;
    bottom: -38px;
    right: 60px;
    width: 0;
    height: 0;
    border-left: 15px solid transparent;
    border-right: 15px solid transparent;
    border-top: 40px solid #000;
    transform: rotate(-20deg);
  }
  .ben-title {
    font-size: 38px;
    font-weight: 900;
    line-height: 1;
    text-align: center;
    margin-bottom: 15px;
  }
  .ben-subtitle {
    font-family: "Times New Roman", Times, serif;
    font-style: italic;
    font-size: 16px;
    margin-bottom: 15px;
  }
  .ben-text {
    font-family: "Times New Roman", Times, serif;
    font-size: 15px;
    line-height: 1.4;
    margin-bottom: 15px;
  }
  .ben-footer {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
  }
  .ben-company {
    font-size: 11px;
    line-height: 1.3;
  }
  .ben-company-name {
    font-size: 20px;
    font-weight: 900;
    line-height: 1.1;
    margin: 5px 0;
  }
  .ben-photo {
    width: 80px;
    height: 90px;
  }

  /* Middle Column Top */
  .col-middle-top {
    grid-column: 2;
    grid-row: 1;
    display: flex;
    flex-direction: column;
  }
  .adv-index-title {
    font-size: 16px;
    font-weight: bold;
    text-align: center;
    letter-spacing: 1px;
    margin-bottom: 20px;
  }
  .adv-item {
    text-align: center;
    margin-bottom: 12px;
    font-size: 14px;
    line-height: 1.2;
  }
  .adv-item-name {
    text-transform: uppercase;
  }
  .adv-item-page {
    font-size: 16px;
  }
  .adv-divider {
    border-top: 1px solid #000;
    margin: 10px 0 20px 0;
  }

  /* Right Column Top */
  .col-right-top {
    grid-column: 3;
    grid-row: 1;
    display: flex;
    flex-direction: column;
  }
  .cal-header {
    border-top: 4px solid #000;
    border-bottom: 4px solid #000;
    padding: 5px 0;
    text-align: center;
    margin-bottom: 20px;
  }
  .cal-title {
    font-size: 28px;
    font-weight: 900;
    letter-spacing: 2px;
  }
  .cal-item {
    margin-bottom: 20px;
    font-size: 13px;
    line-height: 1.4;
  }
  .cal-date {
    text-align: center;
    font-weight: bold;
    margin-bottom: 5px;
  }

  /* Hamilton Ad */
  .hamilton-ad {
    grid-column: 2 / span 2;
    grid-row: 2;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 30px;
  }
  .hamilton-left {
    display: flex;
    flex-direction: column;
  }
  .hamilton-black-box {
    background-color: #000;
    color: #fff;
    padding: 30px 20px;
    text-align: center;
    position: relative;
  }
  .hamilton-bb-text1 {
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 10px;
    line-height: 1.2;
  }
  .hamilton-bb-text2 {
    font-family: "Brush Script MT", cursive, serif;
    font-size: 42px;
    margin-bottom: 5px;
  }
  .hamilton-bb-text3 {
    font-size: 22px;
    font-weight: bold;
  }
  .hamilton-dashed-line {
    position: absolute;
    bottom: -30px;
    left: 60%;
    width: 2px;
    height: 50px;
    border-left: 2px dashed #fff;
    transform: rotate(20deg);
    z-index: 10;
  }
  .hamilton-img {
    width: 100%;
    height: 220px;
  }
  .hamilton-desc {
    font-size: 11px;
    line-height: 1.4;
    margin: 15px 0;
  }
  .tsquare-logo-row {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 10px;
  }
  .tsquare-t {
    border: 2px solid #000;
    font-size: 36px;
    font-weight: bold;
    font-family: "Times New Roman", Times, serif;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-right: 5px;
  }
  .tsquare-name {
    font-size: 24px;
    letter-spacing: 1px;
  }
  .tsquare-details {
    text-align: center;
    font-size: 12px;
    line-height: 1.4;
  }
  .tsquare-details strong {
    font-size: 14px;
  }
  .tsquare-services {
    text-align: center;
    font-size: 10px;
    font-weight: bold;
    margin-top: 10px;
    line-height: 1.5;
  }

  .hamilton-right {
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding-left: 20px;
  }
  .hamilton-bullet {
    display: flex;
    margin-bottom: 20px;
    font-size: 14px;
    line-height: 1.5;
  }
  .hamilton-bullet::before {
    content: '■';
    margin-right: 10px;
    font-size: 14px;
    position: relative;
    top: 1px;
  }
  .hamilton-patent {
    font-size: 11px;
    margin-top: 20px;
  }

  /* Footer */
  .page-footer {
    border-top: 1px solid #000;
    margin-top: 40px;
    padding-top: 10px;
    display: flex;
    justify-content: space-between;
    font-size: 14px;
    text-transform: uppercase;
  }
</style>
</head>
